import com.webcommander.client.ApiResponse;
import java.util.List;
import java.util.Map;

ApiResponse response = client.shippingRules().listShippingRules(Map.of("zone_id", 5, "method", "flat_rate", "handling_cost", "without_handling", "sort", "name", "order", "asc"));
Map<?, ?> body = (Map<?, ?>) response.getMap();
for (Object row : (List<?>) body.get("shipping_rules")) {
    Map<?, ?> rule = (Map<?, ?>) row;
    System.out.println(rule.get("id") + " " + rule.get("name") + " " + rule.get("shipping_rate"));
}
System.out.println(((Map<?, ?>) body.get("pagination")).get("has_next"));

